INSERT INTO `stress_level` (`level_code`, `level_name`, `severity_rank`, `color_hex`, `description`, `requires_alert`) VALUES
  (0, 'Low', 1, '#2E9E5B', 'Language indicates stable or positive emotional state. Routine monitoring only.', 0),
  (1, 'Medium', 2, '#E8A33D', 'Early warning signs present. Suggest self-help resources and re-check in a week.', 0),
  (2, 'High', 3, '#D64545', 'Strong distress indicators. Requires counsellor review and follow-up.', 1);
INSERT INTO `theme` (`theme_id`, `theme_code`, `theme_name`, `category`, `description`) VALUES
  (1, 'academics', 'Academic Pressure', 'Academic', 'Exams, grades, coursework load and academic competition.'),
  (2, 'burnout', 'Burnout & Exhaustion', 'Occupational', 'Emotional depletion, loss of motivation, chronic fatigue.'),
  (3, 'family', 'Family Issues', 'Personal', 'Conflict, expectations or illness within the family.'),
  (4, 'finance', 'Financial Stress', 'Financial', 'Fees, loans, allowance shortfalls and money-related worry.'),
  (5, 'future_worry', 'Future Uncertainty', 'Personal', 'Career direction, placements and fear about what comes next.'),
  (6, 'health', 'Physical Health', 'Health', 'Illness, diet, exercise neglect and somatic complaints.'),
  (7, 'loneliness', 'Loneliness', 'Social', 'Social isolation and lack of meaningful connection.'),
  (8, 'relationships', 'Relationships', 'Social', 'Romantic and close interpersonal difficulties.'),
  (9, 'self_esteem', 'Self-Esteem', 'Personal', 'Self-worth, self-criticism and body image concerns.'),
  (10, 'sleep', 'Sleep Disturbance', 'Health', 'Insomnia, irregular sleep cycles and daytime tiredness.'),
  (11, 'social_anxiety', 'Social Anxiety', 'Social', 'Fear of judgement and avoidance of social situations.'),
  (12, 'time_management', 'Time Management', 'Academic', 'Procrastination, missed deadlines and scheduling overload.'),
  (13, 'work', 'Work / Internship', 'Occupational', 'Job, internship and workplace-related pressure.');
