INSERT INTO `helpline` (`helpline_id`, `name`, `phone`, `dial`, `region`, `hours`, `service`, `is_crisis`, `display_order`, `is_active`) VALUES
  (1, 'Emergency services', '112', '112', 'Emergency', '24×7', 'Police, fire and ambulance. Call if you are in immediate danger or have hurt yourself.', 1, 1, 1),
  (2, 'Tele-MANAS (Govt. of India)', '14416 / 1800-89-14416', '14416', 'National', '24×7, free', 'Government mental health helpline, in English and 20 Indian languages.', 1, 1, 1),
  (3, 'Vandrevala Foundation', '+91 99996 66555', '+919999666555', 'National', '24×7, call or WhatsApp', 'Free crisis counselling for depression, anxiety and distress.', 1, 2, 1),
  (4, 'iCALL (TISS)', '+91 91529 87821', '+919152987821', 'National', 'Mon–Sat, 8 am–9 pm', 'Free counselling by trained professionals.', 0, 3, 1),
  (5, 'Sumaitri', '011-46018404 / +91-9315767849', '01146018404', 'Delhi NCR', 'Daily, 12:30–5 pm', 'Emotional support for anyone in distress or feeling suicidal.', 1, 1, 1),
  (6, 'Sanjivini Society for Mental Health', '011-4076 9002 / 011-4109 2787', '01140769002', 'Delhi NCR', 'Mon–Fri, 10 am–7:30 pm', 'Free, confidential counselling for adults (18+).', 0, 2, 1),
  (7, 'Fortis Stress Helpline', '+91 83768 04102', '+918376804102', 'Delhi NCR', '24×7', 'Stress and mental health support from Fortis Healthcare specialists.', 0, 3, 1),
  (8, 'IHBAS (Govt. of NCT of Delhi)', '011-22114021', '01122114021', 'Delhi NCR', 'Hospital line', 'Government psychiatric hospital, Dilshad Garden. Ask for Emergency Psychiatry (ext. 414).', 0, 4, 1),
  (9, 'Amity Centre for Guidance and Counselling', '1800-102-6489', '18001026489', 'Noida', '24×7 toll-free', 'Amity University''s own counselling centre, H-6 Block near Gate 4A, Sector 125. Office 0120-439-1650, Mon–Sat.', 1, 1, 1),
  (10, 'District Government Combined Hospital', '+91 92664 15010', '+919266415010', 'Noida', 'Hospital line', 'Government hospital, Sector 39, Noida. Ask for the psychiatry OPD.', 0, 2, 1),
  (11, 'GIMS Hospital, Greater Noida', '0120-2341024', '01202341024', 'Noida', 'Emergency control room', 'Government Institute of Medical Sciences. Control room also on 73038 84224.', 0, 3, 1);
INSERT INTO `support_tip` (`tip_id`, `level_code`, `tip_type`, `title`, `body`, `display_order`) VALUES
  (1, 0, 'COPING', 'Keep a steady sleep window', 'Go to bed and wake up at about the same time every day, weekends included. Most students need 7 to 9 hours.', 1),
  (2, 0, 'COPING', 'Move for 20 minutes', 'A brisk walk, a game, cycling or yoga on most days lifts your mood and burns off stress.', 2),
  (3, 0, 'COPING', 'Three good things', 'Before sleeping, write down three things that went well today, however small. It trains your attention toward what is working.', 3),
  (4, 0, 'COPING', 'Screen-free edges of the day', 'Keep your phone away for the first 30 minutes after waking and the last hour before bed.', 4),
  (5, 0, 'ADVICE', 'Keep doing what works', 'Your words read as settled. Notice which habits are helping and protect time for them.', 1),
  (6, 0, 'ADVICE', 'Stay connected', 'Regular time with friends and family is one of the strongest protections against stress.', 2),
  (7, 0, 'ADVICE', 'Check in now and then', 'A quick entry every week or two helps you notice early if things start to change.', 3),
  (8, 0, 'ADVICE', 'Look out for others', 'If a friend seems low, a simple "how are you really doing?" can make a big difference.', 4),
  (9, 1, 'COPING', 'Box breathing', 'Breathe in for 4 counts, hold for 4, breathe out for 4, hold for 4. Repeat for two or three minutes whenever you feel tense.', 1),
  (10, 1, 'COPING', 'Shrink the task', 'Work in 25-minute blocks with a 5-minute break in between. Start with the smallest possible step, not the whole assignment.', 2),
  (11, 1, 'COPING', 'A daily worry window', 'Give worries a fixed 15 minutes a day and write them down. When they come up at other times, remind yourself they have a slot later.', 3),
  (12, 1, 'COPING', 'Wind down before bed', 'Dim the lights, put screens away and do something calm for 30 to 60 minutes before sleep. Avoid caffeine after 3 pm.', 4),
  (13, 1, 'COPING', 'Get some daylight', '10 to 15 minutes outdoors, ideally in the morning, helps both mood and sleep.', 5),
  (14, 1, 'ADVICE', 'Talk to someone you trust', 'Tell a friend, family member or mentor how you have been feeling. Saying it out loud often makes it lighter.', 1),
  (15, 1, 'ADVICE', 'Book a counselling check-in', 'Contact your college counselling cell or one of the helplines below in the next week or two. You do not have to be in crisis to ask for help.', 2),
  (16, 1, 'ADVICE', 'Ask for practical help early', 'If deadlines or workload are the cause, speak to your faculty or mentor now about priorities or extensions.', 3),
  (17, 1, 'ADVICE', 'Re-check in a week', 'Take the full assessment again in about a week to see whether things are easing.', 4),
  (18, 2, 'COPING', '5-4-3-2-1 grounding', 'Name 5 things you can see, 4 you can touch, 3 you can hear, 2 you can smell and 1 you can taste. It pulls your mind back to the present moment.', 1),
  (19, 2, 'COPING', 'Longer out-breaths', 'Breathe in through your nose for 4 counts and out slowly through your mouth for 6. A longer breath out calms the body within a few minutes.', 2),
  (20, 2, 'COPING', 'Cold water reset', 'Splash cold water on your face or hold something cold for 30 seconds. It can quickly take the edge off a wave of panic.', 3),
  (21, 2, 'COPING', 'Don''t stay alone with it', 'Go where people are, such as a friend''s room or a common area, or call someone. Company makes intense feelings easier to ride out.', 4),
  (22, 2, 'COPING', 'Make your space safe', 'If you are having thoughts of hurting yourself, move away from anything you could use to do so, and call a helpline now.', 5),
  (23, 2, 'ADVICE', 'Talk to someone today', 'Call one of the 24×7 helplines below or tell someone you trust. You do not have to handle this on your own.', 1),
  (24, 2, 'ADVICE', 'If you are in danger, call 112', 'If you are at immediate risk or have already hurt yourself, call 112 or go to the nearest hospital emergency department now.', 2),
  (25, 2, 'ADVICE', 'Say yes to support', 'If a counsellor contacts you after this, please accept. You can also reach your college counselling cell directly.', 3),
  (26, 2, 'ADVICE', 'Tell someone close', 'Let a friend, roommate, warden or family member know how you are feeling, so you are not alone tonight.', 4),
  (27, 2, 'ADVICE', 'Get a professional assessment', 'Distress this strong, especially if it has lasted two weeks or more, deserves a proper assessment by a psychologist or psychiatrist.', 5);
INSERT INTO `instrument` (`instrument_id`, `code`, `name`, `full_name`, `measures`, `recall_period`, `item_count`, `option_min`, `option_max`, `score_min`, `score_max`, `weight`, `display_order`, `source_note`, `is_active`) VALUES
  (1, 'PHQ-9', 'PHQ-9', 'Patient Health Questionnaire-9', 'Depression', 'Last 2 weeks', 9, 0, 3, 0, 27, 0.3, 1, 'Kroenke, Spitzer & Williams (2001). Free to reproduce.', 1),
  (2, 'GAD-7', 'GAD-7', 'Generalised Anxiety Disorder-7', 'Anxiety', 'Last 2 weeks', 7, 0, 3, 0, 21, 0.3, 2, 'Spitzer, Kroenke, Williams & Lowe (2006). Free to reproduce.', 1),
  (3, 'PSS-10', 'PSS-10', 'Perceived Stress Scale-10', 'Perceived stress', 'Last month', 10, 0, 4, 0, 40, 0.2, 3, 'Cohen, Kamarck & Mermelstein (1983). Free for educational and research use. Items 4, 5, 7 and 8 are reverse-scored.', 1);
