INSERT INTO `severity_band` (`band_id`, `instrument_id`, `band_name`, `min_score`, `max_score`, `severity_rank`, `color_hex`, `guidance`) VALUES
  (1, 1, 'Minimal', 0, 4, 1, '#2E9E5B', 'No action needed beyond routine self-care. Re-screen if things change.'),
  (2, 1, 'Mild', 5, 9, 2, '#7FB069', 'Watchful waiting. Self-help resources and a re-screen in two weeks.'),
  (3, 1, 'Moderate', 10, 14, 3, '#E8A33D', 'A counselling appointment is recommended.'),
  (4, 1, 'Moderately severe', 15, 19, 4, '#E07A34', 'Active treatment is indicated. Book a counsellor promptly.'),
  (5, 1, 'Severe', 20, 27, 5, '#D64545', 'Priority referral. Same-week professional contact strongly advised.'),
  (6, 2, 'Minimal', 0, 4, 1, '#2E9E5B', 'Anxiety is within the typical range.'),
  (7, 2, 'Mild', 5, 9, 2, '#7FB069', 'Monitor. Breathing and grounding exercises often help at this level.'),
  (8, 2, 'Moderate', 10, 14, 3, '#E8A33D', 'A counselling appointment is recommended.'),
  (9, 2, 'Severe', 15, 21, 4, '#D64545', 'Priority referral for anxiety management support.'),
  (10, 3, 'Low', 0, 13, 1, '#2E9E5B', 'Perceived stress is low. Current coping strategies are working.'),
  (11, 3, 'Moderate', 14, 26, 2, '#E8A33D', 'Moderate perceived stress. Worth reviewing workload and routines.'),
  (12, 3, 'High', 27, 40, 3, '#D64545', 'High perceived stress. Structured support is recommended.');
