INSERT INTO `age_group` (`age_group_id`, `code`, `label`, `min_age`, `max_age`, `difficulty`, `description`) VALUES
  (1, 'JUNIOR', 'Junior', 1, 10, 1, 'Friendly, slower puzzles for children aged 1 to 10.'),
  (2, 'INTERMEDIATE', 'Intermediate', 11, 20, 2, 'Puzzles for ages 11 to 20, from school to early college.'),
  (3, 'ADVANCED', 'Advanced', 21, 120, 3, 'The most demanding puzzles, for ages 21 and over.');
INSERT INTO `puzzle_category` (`category_id`, `code`, `name`, `skill`, `instructions`, `display_order`) VALUES
  (1, 'LOGIC', 'Logical reasoning', 'Reasoning', 'Read carefully and choose the answer that must be true.', 1),
  (2, 'NUMBER', 'Number series', 'Numerical thinking', 'Find the rule and choose the number that comes next.', 2),
  (3, 'STROOP', 'Colour-word focus', 'Attention', 'Choose the colour of the ink, not the word you read. Be quick.', 3),
  (4, 'PATTERN', 'Colour patterns', 'Visual patterns', 'Spot the repeating pattern and choose the missing colour.', 4),
  (5, 'CODE', 'Colour codes', 'Working memory', 'Use the colour key to crack the code.', 5);
INSERT INTO `aptitude_band` (`band_id`, `label`, `min_pct`, `max_pct`, `color_hex`, `message`) VALUES
  (1, 'Keep practising', 0.0, 49.9, '#D9774A', 'Today felt harder. Focus and memory dip when we are stressed, tired or busy, so be kind to yourself and try again another day.'),
  (2, 'Fair', 50.0, 69.9, '#E8A33D', 'Not bad at all. A few puzzles slowed you down, which is completely normal. A little practice makes a real difference.'),
  (3, 'Good', 70.0, 84.9, '#3F4FD8', 'A solid result. You handled most puzzles well, and the tricky ones will get easier with practice.'),
  (4, 'Excellent', 85.0, 100.0, '#2E9E5B', 'Sharp and focused today. Your reasoning and attention were working really well.');
INSERT INTO `puzzle` (`puzzle_id`, `category_id`, `age_group_id`, `prompt`, `explanation`, `time_limit_sec`, `is_active`) VALUES
  (1, 1, 1, 'Which of these animals can fly?', 'A parrot is a bird, and birds can fly. Dogs, cows and goats cannot.', 90, 1),
  (2, 1, 1, 'Monday, Tuesday, Wednesday, ... Which day comes next?', 'The days of the week go Monday, Tuesday, Wednesday, Thursday.', 90, 1),
  (3, 1, 1, 'Which one does not belong with the others?', 'Apple, banana and mango are fruits. A carrot is a vegetable.', 90, 1),
  (4, 1, 1, 'Pen is to write as knife is to ___.', 'A pen is used to write, and a knife is used to cut.', 90, 1),
  (5, 1, 1, 'All cats have tails. Tom is a cat. What must be true?', 'Every cat has a tail, and Tom is a cat, so Tom has a tail.', 90, 1),
  (6, 1, 1, 'Riya is taller than Aman. Aman is taller than Dev. Who is the shortest?', 'Riya is taller than Aman, who is taller than Dev, so Dev is the shortest.', 90, 1),
  (7, 2, 1, 'Which number comes next?', 'The rule is: count on by 10 each time. So the next number is 54.', 60, 1),
  (8, 2, 1, 'Which number comes next?', 'The rule is: count on by 5 each time. So the next number is 27.', 60, 1),
  (9, 2, 1, 'Which number comes next?', 'The rule is: count on by 10 each time. So the next number is 58.', 60, 1),
  (10, 2, 1, 'Which number comes next?', 'The rule is: count on by 5 each time. So the next number is 32.', 60, 1),
  (11, 2, 1, 'Which number comes next?', 'The rule is: count on by 1 each time. So the next number is 6.', 60, 1),
  (12, 2, 1, 'Which number comes next?', 'The rule is: count on by 2 each time. So the next number is 17.', 60, 1),
  (13, 2, 1, 'Which number comes next?', 'The rule is: count on by 2 each time. So the next number is 16.', 60, 1),
  (14, 2, 1, 'Which number comes next?', 'The rule is: count on by 10 each time. So the next number is 56.', 60, 1),
  (15, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Orange, but it is printed in Pink ink.', 15, 1),
  (16, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Red, but it is printed in Green ink.', 15, 1),
  (17, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Red, but it is printed in Orange ink.', 15, 1),
  (18, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Blue, but it is printed in Purple ink.', 15, 1),
  (19, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Green, but it is printed in Pink ink.', 15, 1),
  (20, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Blue, but it is printed in Pink ink.', 15, 1),
  (21, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Purple, but it is printed in Red ink.', 15, 1),
  (22, 3, 1, 'What colour is the ink? Ignore what the word says.', 'The word says Blue, but it is printed in Orange ink.', 15, 1),
  (23, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Orange, Red.', 40, 1),
  (24, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Red, Purple.', 40, 1),
  (25, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Green, Red.', 40, 1),
  (26, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Purple, Pink.', 40, 1),
  (27, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Purple, Blue.', 40, 1),
  (28, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Blue, Pink.', 40, 1),
  (29, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Pink, Blue.', 40, 1),
  (30, 4, 1, 'Which colour comes next?', 'The pattern repeats every 2 colours: Pink, Purple.', 40, 1),
  (31, 5, 1, 'Add the numbers for these two colours.', 'Blue is 4 and Pink is 3, so 4 + 3 = 7.', 60, 1),
  (32, 5, 1, 'Add the numbers for these two colours.', 'Green is 5 and Pink is 2, so 5 + 2 = 7.', 60, 1),
  (33, 5, 1, 'Add the numbers for these two colours.', 'Orange is 5 and Red is 3, so 5 + 3 = 8.', 60, 1),
  (34, 5, 1, 'Add the numbers for these two colours.', 'Green is 3 and Purple is 5, so 3 + 5 = 8.', 60, 1),
  (35, 5, 1, 'Add the numbers for these two colours.', 'Red is 2 and Green is 5, so 2 + 5 = 7.', 60, 1),
  (36, 5, 1, 'Add the numbers for these two colours.', 'Orange is 1 and Pink is 4, so 1 + 4 = 5.', 60, 1),
  (37, 5, 1, 'Add the numbers for these two colours.', 'Blue is 2 and Orange is 5, so 2 + 5 = 7.', 60, 1),
  (38, 5, 1, 'Add the numbers for these two colours.', 'Green is 1 and Purple is 2, so 1 + 2 = 3.', 60, 1),
  (39, 1, 2, 'Book is to library as painting is to ___.', 'Books are kept in a library, and paintings are displayed in a gallery.', 60, 1),
  (40, 1, 2, 'Which one is the odd one out?', 'A cube is a solid 3D shape. The others are flat 2D shapes.', 60, 1),
  (41, 1, 2, 'Some doctors are singers. All singers are cheerful. Which statement must be true?', 'The doctors who are singers must be cheerful, so at least some doctors are cheerful.', 60, 1),
  (42, 1, 2, 'A clock shows exactly 3:00. What is the angle between the hands?', 'Each hour mark is 30°, and the hands are 3 hours apart: 3 × 30° = 90°.', 60, 1),
  (43, 1, 2, 'If CAT is written as DBU, how is DOG written?', 'Each letter moves one step forward: D becomes E, O becomes P and G becomes H.', 60, 1),
  (44, 1, 2, 'Asha sits left of Bala, Bala left of Chirag, Chirag left of Diya, and Diya left of Esha. Who sits in the middle?', 'The order is Asha, Bala, Chirag, Diya, Esha, so Chirag is in the middle.', 60, 1),
  (45, 2, 2, 'Which number comes next?', 'The rule is: square numbers plus 1. So the next number is 37.', 50, 1),
  (46, 2, 2, 'Which number comes next?', 'The rule is: add 2 each time. So the next number is 11.', 40, 1),
  (47, 2, 2, 'Which number comes next?', 'The rule is: the gap grows by 3 each time. So the next number is 48.', 50, 1),
  (48, 2, 2, 'Which number comes next?', 'The rule is: add 5 each time. So the next number is 26.', 40, 1),
  (49, 2, 2, 'Which number comes next?', 'The rule is: the gap grows by 3 each time. So the next number is 49.', 50, 1),
  (50, 2, 2, 'Which number comes next?', 'The rule is: square numbers plus 3. So the next number is 39.', 50, 1),
  (51, 2, 2, 'Which number comes next?', 'The rule is: add 8 each time. So the next number is 52.', 40, 1),
  (52, 2, 2, 'Which number comes next?', 'The rule is: add 8 each time. So the next number is 45.', 40, 1),
  (53, 3, 2, 'What colour is the ink? Ignore what the word says.', 'The word says Orange, but it is printed in Green ink.', 12, 1),
  (54, 3, 2, 'What colour is the ink? Ignore what the word says.', 'The word says Red, but it is printed in Blue ink.', 10, 1),
  (55, 3, 2, 'What colour is the ink? Ignore what the word says.', 'The word says Red, but it is printed in Purple ink.', 8, 1),
  (56, 3, 2, 'What colour is the ink? Ignore what the word says.', 'The word says Pink, but it is printed in Blue ink.', 10, 1),
  (57, 3, 2, 'What colour is the ink? Ignore what the word says.', 'The word says Red, but it is printed in Orange ink.', 10, 1),
