INSERT INTO `place` (`place_id`, `code`, `name`, `helps_with`, `color_hex`, `display_order`) VALUES
  (1, 'HOSPITAL', 'Hospital', 'Injuries, sudden illness and anything that needs a doctor or an ambulance.', '#E5484D', 1),
  (2, 'POLICE', 'Police station', 'Crime, danger from other people, lost children and online fraud.', '#3E63DD', 2),
  (3, 'FIRE', 'Fire station', 'Fire, smoke, gas leaks, sparking wires and dangerous chemicals.', '#F17A1A', 3),
  (4, 'SCHOOL', 'School', 'Bullying, lessons, and problems with classes or the college office.', '#E8A33D', 4),
  (5, 'VET', 'Vet clinic', 'Animals that are hurt, sick or poisoned.', '#2F9E62', 5),
  (6, 'COUNSEL', 'Counselling centre', 'Feelings that are too heavy to carry alone: sadness, worry and stress.', '#8E4EC6', 6);
INSERT INTO `scenario` (`scenario_id`, `age_group_id`, `correct_place_id`, `icon`, `title`, `story`, `explanation`, `urgency`, `time_limit_sec`, `is_opening`, `is_active`) VALUES
  (1, 1, 1, '🚗', 'Road accident', 'A car hit a cyclist. The cyclist is hurt and bleeding on the road.', 'People who are hurt need doctors. An ambulance takes them to hospital. Call 112.', 3, 30, 1, 1),
  (2, 1, 3, '🔥', 'House on fire', 'Smoke and flames are coming out of a house window.', 'Firefighters put out fires. Get out, stay out, and call 112.', 3, 30, 0, 1),
  (3, 1, 5, '🐶', 'Hurt puppy', 'A puppy has hurt its leg and is limping.', 'A vet is a doctor for animals.', 1, 30, 0, 1),
  (4, 1, 2, '👜', 'Stolen bag', 'Someone snatched a lady''s bag and ran away.', 'The police catch thieves and help people who have been robbed.', 2, 30, 0, 1),
  (5, 1, 1, '🤕', 'Fell off the swing', 'A child fell off a swing and cannot move their arm.', 'A doctor can check whether the arm is broken and fix it.', 2, 30, 0, 1),
  (6, 1, 4, '😟', 'Bullied at school', 'Some older kids keep teasing your friend at break time.', 'Tell a teacher. Teachers stop bullying at school.', 1, 30, 0, 1),
  (7, 1, 2, '🧒', 'Lost child', 'A little child is crying alone in the market and cannot find their parents.', 'Police help lost children find their families. Stay with the child near a shop counter.', 2, 30, 0, 1),
  (8, 1, 5, '🐦', 'Injured bird', 'A bird has a hurt wing and cannot fly.', 'A vet can look after hurt birds and animals.', 1, 30, 0, 1),
  (9, 1, 6, '😢', 'Feeling sad', 'You have felt sad and alone for many days and you do not know why.', 'Counsellors listen and help with big feelings. You can also tell a parent or a teacher.', 1, 30, 0, 1),
  (10, 1, 3, '🗑️', 'Bin on fire', 'A rubbish bin outside your building has caught fire.', 'Keep away from the smoke and tell an adult to call the fire service.', 2, 30, 0, 1),
  (11, 1, 4, '📚', 'Help with lessons', 'Your maths lesson was confusing and there is a test soon.', 'Teachers are happy to explain a lesson again. Just ask.', 1, 30, 0, 1),
  (12, 1, 1, '🤒', 'Very high fever', 'Your little brother has a very high fever and is very sleepy.', 'A high fever with sleepiness needs a doctor quickly.', 2, 30, 0, 1),
  (13, 1, 2, '🚲', 'Bicycle stolen', 'Your bicycle was stolen from outside the shop.', 'Tell the police. They keep records and look for stolen things.', 1, 30, 0, 1),
  (14, 2, 1, '🏍️', 'Accident on the highway', 'Two bikes collided. One rider is lying on the road and is not waking up.', 'An unconscious person needs an ambulance straight away. Call 112 and do not move them unless they are in danger.', 3, 20, 1, 1),
  (15, 2, 3, '⚡', 'Sparking wires', 'Electric wires are sparking and a small fire has started near a shop.', 'Fire and electricity together need firefighters. Keep well away and call 112.', 3, 20, 0, 1),
  (16, 2, 2, '📱', 'Online threat', 'A stranger online says they will post your photos unless you pay them.', 'This is a crime. Save the messages, do not pay, and report it to the police or the cyber crime helpline 1930.', 2, 20, 0, 1),
  (17, 2, 5, '🐕', 'Dog hit by a scooter', 'A street dog was hit by a scooter and is bleeding.', 'An injured animal needs a vet or an animal rescue service.', 2, 20, 0, 1),
  (18, 2, 6, '😰', 'Panic before exams', 'Your heart races, you cannot sleep, and you are sure you will fail every exam.', 'Exam anxiety is common and it can be helped. A counsellor can teach you ways to calm your body and plan your studies.', 1, 20, 0, 1),
  (19, 2, 1, '🤢', 'Food poisoning', 'After eating at a stall, your friend keeps vomiting and feels faint.', 'Repeated vomiting and feeling faint can mean dangerous loss of fluids. See a doctor.', 2, 20, 0, 1),
  (20, 2, 3, '💨', 'Smell of gas', 'There is a strong smell of cooking gas in the kitchen.', 'Do not switch anything on or off. Open the windows, get everyone out, and call the fire service or the LPG emergency line 1906.', 3, 20, 0, 1),
  (21, 2, 2, '👀', 'Someone following you', 'A stranger has followed you home from school for three days.', 'Tell a trusted adult and the police. You can call 112 at any time.', 2, 20, 0, 1),
  (22, 2, 6, '😞', 'Friend has given up', 'Your friend has stopped eating properly and says nothing matters any more.', 'Stay with them, listen, and help them talk to a counsellor. If they talk about hurting themselves, call 112 or Tele-MANAS 14416.', 2, 20, 0, 1),
  (23, 2, 4, '📖', 'Falling behind', 'You have missed several classes and are falling behind in one subject.', 'Talk to your teacher or class advisor. They can arrange extra help.', 1, 20, 0, 1),
  (24, 2, 2, '🚨', 'Shop break-in', 'At night you see two people breaking the lock of a shop.', 'Do not go near them. Call 112 from a safe place.', 3, 20, 0, 1),
  (25, 2, 1, '🦶', 'Sports injury', 'During a match a player twisted their ankle badly and it is swelling fast.', 'A badly swollen ankle may be broken. It needs an X-ray at a hospital.', 2, 20, 0, 1),
  (26, 2, 5, '🐄', 'Cow with a deep cut', 'A cow on the road has a deep cut on its leg.', 'Large animals need a vet too. Many towns have an animal helpline.', 1, 20, 0, 1),
  (27, 2, 4, '💬', 'Rumours in the group chat', 'Classmates are spreading rumours about you in the class group chat.', 'Take screenshots and tell a teacher. Schools must act on bullying, including online.', 1, 20, 0, 1),
  (28, 3, 1, '🚶', 'Pedestrian hit at a junction', 'A pedestrian was hit by a car. They are awake but cannot feel their legs.', 'This could be a spinal injury. Keep them still, do not move them, and call 112 for an ambulance.', 3, 15, 1, 1),
  (29, 3, 3, '🏢', 'Smoke in the stairwell', 'The fire alarm is ringing and the office stairwell is filling with smoke.', 'Use the stairs, never the lift. Stay low under the smoke and call 112 once you are outside.', 3, 15, 0, 1),
  (30, 3, 2, '💳', 'Bank fraud call', 'You shared an OTP on a phone call and money has just left your account.', 'Call the cyber crime helpline 1930 at once. Reporting within the first hour gives the best chance of stopping the money.', 2, 15, 0, 1),
  (31, 3, 1, '💔', 'Crushing chest pain', 'Your uncle suddenly has crushing chest pain spreading to his left arm, and he is sweating.', 'These are signs of a heart attack. Call 112 at once; every minute matters.', 3, 15, 0, 1),
  (32, 3, 3, '🧪', 'Chemical spill', 'A chemical has spilled in the lab and the fumes are making people cough.', 'Leave the area and close the door. The fire service handles dangerous chemicals.', 3, 15, 0, 1),
  (33, 3, 6, '🌧️', 'Colleague struggling', 'A colleague has withdrawn for weeks, is drinking more, and says life feels pointless.', 'Ask how they are, listen, and help them reach a counsellor or Tele-MANAS 14416. If they have a plan to harm themselves, it is an emergency: call 112.', 2, 15, 0, 1),
  (34, 3, 1, '🐕', 'Dog bite', 'A stray dog bit a child in the park and the wound is bleeding.', 'The child needs a doctor, not a vet. Wash the wound with soap and water for 15 minutes and get the rabies vaccine at a hospital the same day.', 3, 15, 0, 1),
  (35, 3, 5, '🐾', 'Pet ate poison', 'Your dog has eaten rat poison from the storeroom.', 'Go to a vet immediately. Do not try to make the dog sick unless the vet tells you to.', 3, 15, 0, 1),
  (36, 3, 2, '🏠', 'Cry for help next door', 'You hear a neighbour screaming for help and things being smashed.', 'Call 112. The police must respond to violence at home. The women''s helpline is 181.', 3, 15, 0, 1),
  (37, 3, 6, '🥱', 'Burnt out', 'For months you have felt exhausted, cannot concentrate and dread every morning.', 'Long-lasting exhaustion and dread are signs of burnout. A counsellor can help you find the cause and a way back.', 1, 15, 0, 1),
  (38, 3, 4, '🗂️', 'Missed registration', 'Your course registration was missed and you might lose a semester.', 'The college office or your academic advisor handles registration and appeals.', 1, 15, 0, 1),
  (39, 3, 1, '👵', 'Elderly neighbour fell', 'An elderly neighbour fell in the bathroom. She is awake but cannot get up and her hip hurts.', 'A painful hip after a fall may be a fracture. Keep her warm and still and call an ambulance.', 2, 15, 0, 1),
  (40, 3, 5, '🦉', 'Owl with a broken wing', 'An owl with a broken wing is lying on your balcony.', 'A vet or wildlife rescue can treat it. Keep it in a covered box somewhere quiet and dark.', 1, 15, 0, 1),
  (41, 3, 4, '👂', 'Student cannot hear lectures', 'A new student has a hearing problem and cannot follow lectures.', 'The school or college must make reasonable adjustments, such as a front seat and shared notes.', 1, 15, 0, 1);
